"""Output, styling, file-opening and directory helpers."""

import os
import re
import sys
import tempfile
import typing as t

from .exceptions import FileError
from .globals import get_current_context

_ANSI_RE = re.compile(r"\x1b\[[0-9;?]*[ -/]*[@-~]")

_NAMED_COLORS = {
    "black": 30,
    "red": 31,
    "green": 32,
    "yellow": 33,
    "blue": 34,
    "magenta": 35,
    "cyan": 36,
    "white": 37,
    "bright_black": 90,
    "bright_red": 91,
    "bright_green": 92,
    "bright_yellow": 93,
    "bright_blue": 94,
    "bright_magenta": 95,
    "bright_cyan": 96,
    "bright_white": 97,
}


def isatty(stream: t.Any) -> bool:
    try:
        return bool(stream.isatty())
    except Exception:
        return False


def is_interactive() -> bool:
    """A session is interactive when stdin is a terminal, or stdin/stdout is a TTY."""
    return isatty(sys.stdin) or isatty(sys.stdout)


def unstyle(text: str) -> str:
    """Remove ANSI style sequences, leaving all other text."""
    return _ANSI_RE.sub("", text)


def _color_code(color: t.Any, background: bool) -> str:
    offset = 10 if background else 0
    if isinstance(color, str):
        if color == "reset":
            return str(49 if background else 39)
        if color in _NAMED_COLORS:
            return str(_NAMED_COLORS[color] + offset)
        raise ValueError(f"Unknown color '{color}'.")
    if isinstance(color, bool):
        raise ValueError(f"Invalid color {color!r}.")
    if isinstance(color, int):
        if 0 <= color <= 255:
            return f"{48 if background else 38};5;{color}"
        raise ValueError(f"Color index {color} is outside 0-255.")
    if isinstance(color, (tuple, list)) and len(color) == 3:
        if all(isinstance(c, int) and not isinstance(c, bool) and 0 <= c <= 255 for c in color):
            r, g, b = color
            return f"{48 if background else 38};2;{r};{g};{b}"
    raise ValueError(f"Invalid color {color!r}.")


def style(
    text: t.Any,
    fg: t.Any = None,
    bg: t.Any = None,
    bold: t.Optional[bool] = None,
    dim: t.Optional[bool] = None,
    underline: t.Optional[bool] = None,
    overline: t.Optional[bool] = None,
    italic: t.Optional[bool] = None,
    blink: t.Optional[bool] = None,
    reverse: t.Optional[bool] = None,
    strikethrough: t.Optional[bool] = None,
    reset: bool = True,
) -> str:
    """Wrap ``text`` in ANSI SGR sequences for the given styles."""
    codes: t.List[str] = []
    if fg is not None:
        codes.append(_color_code(fg, False))
    if bg is not None:
        codes.append(_color_code(bg, True))
    switches = (
        (bold, 1, 22),
        (dim, 2, 22),
        (italic, 3, 23),
        (underline, 4, 24),
        (blink, 5, 25),
        (reverse, 7, 27),
        (strikethrough, 9, 29),
        (overline, 53, 55),
    )
    for flag, on_code, off_code in switches:
        if flag is not None:
            codes.append(str(on_code if flag else off_code))
    message = str(text)
    if not codes:
        return message
    prefix = "".join(f"\x1b[{c}m" for c in codes)
    return prefix + message + ("\x1b[0m" if reset else "")


def _keep_styles(file: t.Any, color: t.Optional[bool]) -> bool:
    if color is None:
        ctx = get_current_context(silent=True)
        if ctx is not None and ctx.color is not None:
            color = ctx.color
    if color is None:
        return isatty(file)
    return bool(color)


def _write_bytes(file: t.Any, data: bytes) -> None:
    buffer = getattr(file, "buffer", None)
    if buffer is not None:
        file.flush()
        buffer.write(data)
        buffer.flush()
    else:
        file.write(data.decode("utf-8", "replace"))


def _write_text(file: t.Any, text: str) -> None:
    encoding = (getattr(file, "encoding", None) or "").lower().replace("_", "-")
    if encoding in ("ascii", "us-ascii"):
        # An ASCII-only stream cannot take ordinary Unicode text; send UTF-8 instead.
        _write_bytes(file, text.encode("utf-8"))
        return
    try:
        file.write(text)
    except UnicodeEncodeError:
        _write_bytes(file, text.encode("utf-8"))


def echo(
    message: t.Any = None,
    file: t.Any = None,
    nl: bool = True,
    err: bool = False,
    color: t.Optional[bool] = None,
) -> None:
    """Write text or bytes to standard output (or standard error, or ``file``)."""
    if file is None:
        file = sys.stderr if err else sys.stdout
    if message is None:
        message = ""
    if isinstance(message, bytes):
        _write_bytes(file, message + (b"\n" if nl else b""))
        return
    text = str(message)
    if nl:
        text += "\n"
    if not _keep_styles(file, color):
        text = unstyle(text)
    _write_text(file, text)
    file.flush()


def secho(
    message: t.Any = None,
    file: t.Any = None,
    nl: bool = True,
    err: bool = False,
    color: t.Optional[bool] = None,
    **styles: t.Any,
) -> None:
    """Echo text with the given styles applied."""
    if message is not None:
        message = style(message, **styles)
    echo(message, file=file, nl=nl, err=err, color=color)


