    """A file that is opened on first use, optionally through an atomic temporary file."""

    def __init__(
        self,
        filename: str,
        mode: str = "r",
        encoding: t.Optional[str] = None,
        errors: str = "strict",
        atomic: bool = False,
    ) -> None:
        self.name = filename
        self.mode = mode
        self.encoding = encoding
        self.errors = errors
        self.atomic = atomic
        self._writing = any(c in mode for c in "wax+")
        self._file: t.Any = None
        self._tmp_path: t.Optional[str] = None

    def open(self) -> t.Any:
        if self._file is not None:
            return self._file
        target = self.name
        try:
            if self.atomic and self._writing:
                directory = os.path.dirname(os.path.abspath(self.name))
                fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".optlyn-", suffix=".tmp")
                os.close(fd)
                self._tmp_path = tmp_path
                target = tmp_path
            if "b" in self.mode:
                handle = open(target, self.mode)
            else:
                handle = open(target, self.mode, encoding=self.encoding, errors=self.errors)
        except OSError as e:
            if self._tmp_path is not None:
                try:
                    os.remove(self._tmp_path)
                except OSError:
                    pass
                self._tmp_path = None
            raise FileError(self.name, e.strerror or str(e)) from e
        self._file = handle
        return handle

    def close(self) -> None:
        if self._file is None:
            return
        self._file.close()
        self._file = None
        if self._tmp_path is not None:
            os.replace(self._tmp_path, self.name)
            self._tmp_path = None

    def __getattr__(self, name: str) -> t.Any:
        if name.startswith("__"):
            raise AttributeError(name)
        return getattr(self.open(), name)

    def __iter__(self) -> t.Iterator[t.Any]:
        return iter(self.open())

    def __enter__(self) -> "LazyFile":
        return self

    def __exit__(self, *exc: t.Any) -> None:
        self.close()

    def __repr__(self) -> str:
        return f"<LazyFile {self.name!r} mode={self.mode!r}>"


def open_file(
    filename: str,
    mode: str = "r",
    encoding: t.Optional[str] = None,
    errors: str = "strict",
    lazy: bool = False,
    atomic: bool = False,
) -> t.Any:
    """Open a file, or the standard stream when ``filename`` is ``-``.

    Standard streams are never closed by the returned object.
    """
    if filename == "-":
        reading = "r" in mode and "+" not in mode
        stream = sys.stdin if reading else sys.stdout
        if "b" in mode:
            stream = stream.buffer
        return _StdStreamProxy(stream)
    lazy_file = LazyFile(filename, mode, encoding, errors, atomic)
    if not lazy:
        lazy_file.open()
    return lazy_file


def format_filename(filename: t.Any, shorten: bool = False) -> str:
    """Turn a path into text that prints and encodes as strict UTF-8 without failing."""
    if isinstance(filename, bytes):
        filename = os.fsdecode(filename)
    else:
        filename = os.fspath(filename)
    if shorten:
        filename = os.path.basename(filename)
    try:
        raw = filename.encode("utf-8", "surrogateescape")
    except UnicodeEncodeError:
        return ascii(filename)[1:-1]
    return raw.decode("utf-8", "backslashreplace")


def get_app_dir(app_name: str, roaming: bool = True, force_posix: bool = False) -> str:
    """Return the per-user configuration directory for ``app_name``."""
    folder = re.sub(r"\s+", "-", app_name.lower())
    home = os.path.expanduser("~")
    if force_posix:
        return os.path.join(home, "." + folder)
    if sys.platform == "darwin":
        return os.path.join(home, "Library", "Application Support", app_name)
    if sys.platform.startswith("win"):
        base = os.environ.get("APPDATA") or os.path.join(home, "AppData", "Roaming")
        return os.path.join(base, app_name)
    config_home = os.environ.get("XDG_CONFIG_HOME") or os.path.join(home, ".config")
    return os.path.join(config_home, folder)

