            return
        self._file.close()
        self._file = None
        if self._tmp_path is not None:
            os.replace(self._tmp_path, self.name)
            self._tmp_path = None

    def __getattr__(self, name: str) -> t.Any:
        if name.startswith("__"):
            raise AttributeError(name)
        return getattr(self.open(), name)

    def __iter__(self) -> t.Iterator[t.Any]:
        return iter(self.open())

    def __enter__(self) -> "LazyFile":
        return self

    def __exit__(self, *exc: t.Any) -> None:
        self.close()

    def __repr__(self) -> str:
        return f"<LazyFile {self.name!r} mode={self.mode!r}>"


def open_file(
    filename: str,
    mode: str = "r",
    encoding: t.Optional[str] = None,
    errors: str = "strict",
    lazy: bool = False,
    atomic: bool = False,
) -> t.Any:
    """Open a file, or the standard stream when ``filename`` is ``-``.

    Standard streams are never closed by the returned object.
    """
    if filename == "-":
        reading = "r" in mode and "+" not in mode
        stream = sys.stdin if reading else sys.stdout
        if "b" in mode:
