class _RangeMixin:
    min: t.Any
    max: t.Any
    min_open: bool
    max_open: bool
    clamp: bool

    def _range_text(self) -> str:
        lo = "" if self.min is None else f"{'>' if self.min_open else '>='}{self.min}"
        hi = "" if self.max is None else f"{'<' if self.max_open else '<='}{self.max}"
        if lo and hi:
            return f"{self.min}{'<' if self.min_open else '<='}x{'<' if self.max_open else '<='}{self.max}"
        if lo:
            return lo
        return hi

    def _check(self, value, param, ctx):
        below = self.min is not None and (value < self.min or (self.min_open and value == self.min))
        above = self.max is not None and (value > self.max or (self.max_open and value == self.max))
        if not below and not above:
            return value
        if self.clamp:
            if below:
                if self.min_open:
                    return self._step_up(self.min)
                return self.min
            if self.min_open is None:  # pragma: no cover - defensive
                return value
            if self.max_open:
                return self._step_down(self.max)
            return self.max
        self.fail(f"{value!r} is not in the range {self._range_text()}.", param, ctx)

    def _step_up(self, v):
        return v + 1

    def _step_down(self, v):
        return v - 1


