    def convert(self, value, param=None, ctx=None):
        if isinstance(value, (str, bytes)) or not hasattr(value, "__len__"):
            self.fail(f"{value!r} is not a sequence of {len(self.types)} values.", param, ctx)
        if len(value) != len(self.types):
            self.fail(f"Takes {len(self.types)} values but {len(value)} were given.", param, ctx)
