class Path(ParamType):
    """A filesystem path, checked against the requested properties."""

    name = "path"
    envvar_separator = os.pathsep

    def __init__(
        self,
        exists: bool = False,
        file_okay: bool = True,
        dir_okay: bool = True,
        writable: bool = False,
        readable: bool = True,
        resolve_path: bool = False,
        allow_dash: bool = False,
        path_type: t.Any = None,
        executable: bool = False,
    ) -> None:
        self.exists = exists
        self.file_okay = file_okay
        self.dir_okay = dir_okay
        self.writable = writable
        self.readable = readable
        self.resolve_path = resolve_path
        self.allow_dash = allow_dash
        self.path_type = path_type
        self.executable = executable

    def _result(self, value: str) -> t.Any:
        if self.path_type is None or self.path_type is str:
            return value
        if self.path_type is os.PathLike or self.path_type.__name__ == "Path":
            import pathlib

            return pathlib.Path(value)
        return self.path_type(value)

    def convert(self, value, param=None, ctx=None):
        if isinstance(value, bytes):
            value = os.fsdecode(value)
        value = os.fspath(value)
        if self.allow_dash and value == "-":
            return self._result(value)
        path = value
        if self.resolve_path:
            path = os.path.realpath(os.path.abspath(path))
        if not os.path.exists(path):
            if self.exists:
                self.fail(f"{value!r} does not exist.", param, ctx)
            return self._result(path)
        if os.path.isdir(path):
            if not self.dir_okay:
                self.fail(f"{value!r} is a directory.", param, ctx)
        elif not self.file_okay:
            self.fail(f"{value!r} is a file.", param, ctx)
        if self.readable and not os.access(path, os.R_OK):
            self.fail(f"{value!r} is not readable.", param, ctx)
        if self.writable and not os.access(path, os.W_OK):
            self.fail(f"{value!r} is not writable.", param, ctx)
        if self.executable and not os.access(path, os.X_OK):
            self.fail(f"{value!r} is not executable.", param, ctx)
        return self._result(path)

    def shell_complete(self, ctx, param, incomplete):
        kind = "dir" if (self.dir_okay and not self.file_okay) else "file"
        return [PathRequest(kind, incomplete)]


class FuncParamType(ParamType):
    """Adapts a conversion function ``f(token) -> value`` that refuses with ``ValueError``."""

    def __init__(self, func: t.Callable[[t.Any], t.Any]) -> None:
        self.func = func
        self.name = getattr(func, "__name__", "text")

    def convert(self, value, param=None, ctx=None):
        try:
            return self.func(value)
        except BadParameter:
            raise
        except ValueError as e:
            self.fail(str(e) or f"{value!r} is not valid.", param, ctx)


STRING = StringParamType()
INT = IntParamType()
FLOAT = FloatParamType()
BOOL = BoolParamType()
UUID = UUIDParamType()
UNPROCESSED = UnprocessedParamType()

_PY_TYPES = {str: STRING, int: INT, float: FLOAT, bool: BOOL, uuid.UUID: UUID}


def _infer_from_default(default: t.Any) -> ParamType:
    if isinstance(default, bool):
        return BOOL
    if isinstance(default, int):
        return INT
    if isinstance(default, float):
        return FLOAT
    if isinstance(default, str):
        return STRING
    return STRING


def convert_type(ty: t.Any, default: t.Any = None) -> ParamType:
    """Return a :class:`ParamType` for ``ty``, inferring it from ``default`` when ``ty`` is None."""
    if ty is None:
        if default is None or callable(default):
            return STRING
        if isinstance(default, (list, tuple)):
            if not default:
                return STRING
            return _infer_from_default(default[0])
        return _infer_from_default(default)
    if isinstance(ty, ParamType):
        return ty
    if isinstance(ty, type):
        if issubclass(ty, ParamType):
            return ty()
        if ty in _PY_TYPES:
            return _PY_TYPES[ty]
    if callable(ty):
        return FuncParamType(ty)
    raise TypeError(f"Unsupported parameter type: {ty!r}")

