"""Parameter types: how command-line tokens become Python values."""

import datetime as dt
import enum
import os
import typing as t
import uuid

from .exceptions import BadParameter
from .utils import LazyFile, open_file


class ParamType:
    """Base class for parameter types.

    Subclasses set :attr:`name` and implement :meth:`convert`. Values that are
    already of the right type must pass through unchanged.
    """

    name = "text"
    #: Separator used to split environment values for multi-value parameters.
    envvar_separator: t.Optional[str] = None

    def __call__(self, value: t.Any, param: t.Any = None, ctx: t.Any = None) -> t.Any:
        return self.convert(value, param, ctx)

    def convert(self, value: t.Any, param: t.Any = None, ctx: t.Any = None) -> t.Any:
        return value

    def fail(self, message: str, param: t.Any = None, ctx: t.Any = None) -> t.NoReturn:
        raise BadParameter(message, ctx=ctx, param=param)

    def get_metavar(self) -> t.Optional[str]:
        """Placeholder shown on help pages, or ``None`` to use the parameter name."""
        return None

    def shell_complete(self, ctx: t.Any, param: t.Any, incomplete: str) -> t.List[t.Any]:
        return []

    def split_envvar_value(self, rv: str) -> t.List[str]:
        sep = self.envvar_separator
        if sep is None:
            return rv.split()
        return [p for p in rv.split(sep) if p != ""]

    def __repr__(self) -> str:
        return self.name.upper()


class StringParamType(ParamType):
    name = "text"

    def convert(self, value, param=None, ctx=None):
        if isinstance(value, bytes):
            return value.decode("utf-8", "replace")
        if isinstance(value, str):
            return value
        return str(value)


class UnprocessedParamType(ParamType):
    """Pass the raw token through unchanged."""

    name = "text"


class IntParamType(ParamType):
    name = "integer"

    def convert(self, value, param=None, ctx=None):
        if isinstance(value, int) and not isinstance(value, bool):
            return value
        if isinstance(value, bool):
            return int(value)
        if isinstance(value, float):
            self.fail(f"{value!r} is not a valid integer.", param, ctx)
        try:
            return int(str(value).strip())
        except (TypeError, ValueError):
            self.fail(f"{value!r} is not a valid integer.", param, ctx)


class FloatParamType(ParamType):
    name = "float"

    def convert(self, value, param=None, ctx=None):
        if isinstance(value, float):
            return value
        if isinstance(value, int) and not isinstance(value, bool):
            return float(value)
        try:
            return float(str(value).strip())
        except (TypeError, ValueError):
            self.fail(f"{value!r} is not a valid floating point value.", param, ctx)


_TRUE = {"1", "true", "t", "yes", "y", "on"}
_FALSE = {"0", "false", "f", "no", "n", "off"}


class BoolParamType(ParamType):
    name = "boolean"

    def convert(self, value, param=None, ctx=None):
        if isinstance(value, bool):
            return value
        text = str(value).strip().lower()
        if text in _TRUE:
            return True
        if text in _FALSE:
            return False
        self.fail(f"{value!r} is not a valid boolean.", param, ctx)


class UUIDParamType(ParamType):
    name = "uuid"

    def convert(self, value, param=None, ctx=None):
        if isinstance(value, uuid.UUID):
            return value
        try:
            return uuid.UUID(str(value).strip())
        except (TypeError, ValueError):
            self.fail(f"{value!r} is not a valid UUID.", param, ctx)


class Choice(ParamType):
    """A closed list of allowed values, or the members of an enumeration."""

    name = "choice"

    def __init__(self, choices: t.Iterable[t.Any], case_sensitive: bool = True) -> None:
        if isinstance(choices, type) and issubclass(choices, enum.Enum):
            self.choices: t.List[t.Any] = list(choices)
            self._is_enum = True
        else:
            self.choices = list(choices)
            self._is_enum = False
        self.case_sensitive = case_sensitive

    def _token(self, choice: t.Any) -> str:
        if self._is_enum:
            return choice.name
        return str(choice)

    def get_metavar(self) -> str:
        return "[" + "|".join(self._token(c) for c in self.choices) + "]"

    def convert(self, value, param=None, ctx=None):
        for choice in self.choices:
            if choice is value or (not self._is_enum and choice == value):
                return choice
        token = value.name if isinstance(value, enum.Enum) else str(value)
        normalize = getattr(ctx, "token_normalize_func", None) if ctx is not None else None
        if normalize is not None:
            token = normalize(token)
        for choice in self.choices:
            candidate = self._token(choice)
            if normalize is not None:
                candidate = normalize(candidate)
            if candidate == token or (
                not self.case_sensitive and candidate.casefold() == token.casefold()
            ):
                return choice
        options = ", ".join(repr(self._token(c)) for c in self.choices)
        self.fail(f"{value!r} is not {'one of' if len(self.choices) != 1 else 'one of'} {options}.", param, ctx)

    def shell_complete(self, ctx, param, incomplete):
        out = []
        for choice in self.choices:
            token = self._token(choice)
            if self.case_sensitive:
                matches = token.startswith(incomplete)
            else:
                matches = token.casefold().startswith(incomplete.casefold())
            if matches:
                out.append(token)
        return out


