class DateTime(ParamType):
    name = "datetime"

    def __init__(self, formats: t.Optional[t.Sequence[str]] = None) -> None:
        self.formats = list(formats) if formats is not None else list(_DEFAULT_DATETIME_FORMATS)

    def get_metavar(self) -> str:
        return "[" + "|".join(self.formats) + "]"

    def convert(self, value, param=None, ctx=None):
        if isinstance(value, dt.datetime):
            return value
        text = str(value).strip()
        for fmt in self.formats:
            try:
                return dt.datetime.strptime(text, fmt)
            except ValueError:
                continue
        self.fail(
            f"{value!r} does not match the format{'s' if len(self.formats) != 1 else ''} "
            f"{', '.join(repr(f) for f in self.formats)}.",
            param,
            ctx,
        )


class _RangeMixin:
    min: t.Any
    max: t.Any
    min_open: bool
    max_open: bool
    clamp: bool

    def _range_text(self) -> str:
        lo = "" if self.min is None else f"{'>' if self.min_open else '>='}{self.min}"
        hi = "" if self.max is None else f"{'<' if self.max_open else '<='}{self.max}"
        if lo and hi:
            return f"{self.min}{'<' if self.min_open else '<='}x{'<' if self.max_open else '<='}{self.max}"
        if lo:
            return lo
        return hi

    def _check(self, value, param, ctx):
        below = self.min is not None and (value < self.min or (self.min_open and value == self.min))
        above = self.max is not None and (value > self.max or (self.max_open and value == self.max))
        if not below and not above:
            return value
        if self.clamp:
            if below:
                if self.min_open:
                    return self._step_up(self.min)
                return self.min
            if self.min_open is None:  # pragma: no cover - defensive
                return value
            if self.max_open:
                return self._step_down(self.max)
            return self.max
        self.fail(f"{value!r} is not in the range {self._range_text()}.", param, ctx)

    def _step_up(self, v):
        return v + 1

    def _step_down(self, v):
        return v - 1


class IntRange(_RangeMixin, IntParamType):
    name = "integer range"

    def __init__(
        self,
        min: t.Optional[int] = None,
        max: t.Optional[int] = None,
        min_open: bool = False,
        max_open: bool = False,
        clamp: bool = False,
    ) -> None:
        self.min = min
        self.max = max
        self.min_open = min_open
        self.max_open = max_open
        self.clamp = clamp
        if min is not None and max is not None and min > max:
            raise ValueError("'min' must not be greater than 'max'.")

    def convert(self, value, param=None, ctx=None):
        value = IntParamType.convert(self, value, param, ctx)
        return self._check(value, param, ctx)

    def _step_up(self, v):
        return v + 1

    def _step_down(self, v):
        return v - 1


class FloatRange(_RangeMixin, FloatParamType):
    name = "float range"

    def __init__(
        self,
        min: t.Optional[float] = None,
        max: t.Optional[float] = None,
        min_open: bool = False,
        max_open: bool = False,
        clamp: bool = False,
    ) -> None:
        self.min = min
        self.max = max
        self.min_open = min_open
        self.max_open = max_open
        self.clamp = clamp
        if min is not None and max is not None and min > max:
            raise ValueError("'min' must not be greater than 'max'.")
        if clamp and (min_open or max_open):
            raise ValueError("Clamping is only allowed when both bounds are closed.")

    def convert(self, value, param=None, ctx=None):
        value = FloatParamType.convert(self, value, param, ctx)
        return self._check(value, param, ctx)


class Tuple(ParamType):
    """A fixed-length product of types, one value per position."""

    name = "tuple"

    def __init__(self, types: t.Sequence[t.Any]) -> None:
        self.types = [convert_type(ty) for ty in types]

    @property
    def arity(self) -> int:
        return len(self.types)

    def get_metavar(self) -> str:
        return " ".join((ty.get_metavar() or ty.name.upper()) for ty in self.types)

    def convert(self, value, param=None, ctx=None):
        if isinstance(value, (str, bytes)) or not hasattr(value, "__len__"):
            self.fail(f"{value!r} is not a sequence of {len(self.types)} values.", param, ctx)
        if len(value) != len(self.types):
            self.fail(f"Takes {len(self.types)} values but {len(value)} were given.", param, ctx)
        return tuple(ty.convert(v, param, ctx) for ty, v in zip(self.types, value))


class File(ParamType):
    """An open file. ``-`` is standard input for reading and standard output for writing."""

    name = "filename"

    def __init__(
        self,
        mode: str = "r",
        encoding: t.Optional[str] = None,
        errors: str = "strict",
        lazy: t.Optional[bool] = None,
        atomic: bool = False,
    ) -> None:
        if mode not in ("r", "w", "rb", "wb"):
            raise ValueError(f"Unsupported file mode {mode!r}.")
        self.mode = mode
        self.encoding = encoding
        self.errors = errors
        self.lazy = lazy
        self.atomic = atomic

    def convert(self, value, param=None, ctx=None):
        if hasattr(value, "read") or hasattr(value, "write"):
            return value
        filename = os.fspath(value) if not isinstance(value, bytes) else os.fsdecode(value)
        if filename == "-":
            return open_file(filename, self.mode, self.encoding, self.errors)
        writing = "w" in self.mode
        lazy = self.lazy if self.lazy is not None else writing
        handle = LazyFile(filename, self.mode, self.encoding, self.errors, self.atomic)
        if not lazy:
            try:
                handle.open()
            except Exception as e:
                self.fail(f"'{filename}': {getattr(e, 'message', e)}", param, ctx)
        if ctx is not None:
            ctx.call_on_close(handle.close)
        return handle

    def get_metavar(self) -> None:
        return None

    def shell_complete(self, ctx, param, incomplete):
        return [PathRequest("file", incomplete)]


class PathRequest:
    """Completion entry that asks the shell to complete filesystem paths."""

    def __init__(self, kind: str, incomplete: str) -> None:
        self.kind = kind
        self.incomplete = incomplete


class Path(ParamType):
    """A filesystem path, checked against the requested properties."""

    name = "path"
    envvar_separator = os.pathsep

    def __init__(
        self,
        exists: bool = False,
        file_okay: bool = True,
        dir_okay: bool = True,
        writable: bool = False,
        readable: bool = True,
        resolve_path: bool = False,
        allow_dash: bool = False,
        path_type: t.Any = None,
        executable: bool = False,
    ) -> None:
        self.exists = exists
        self.file_okay = file_okay
        self.dir_okay = dir_okay
        self.writable = writable
        self.readable = readable
        self.resolve_path = resolve_path
        self.allow_dash = allow_dash
        self.path_type = path_type
        self.executable = executable

    def _result(self, value: str) -> t.Any:
        if self.path_type is None or self.path_type is str:
            return value
        if self.path_type is os.PathLike or self.path_type.__name__ == "Path":
            import pathlib

            return pathlib.Path(value)
        return self.path_type(value)

    def convert(self, value, param=None, ctx=None):
        if isinstance(value, bytes):
            value = os.fsdecode(value)
        value = os.fspath(value)
        if self.allow_dash and value == "-":
            return self._result(value)
        path = value
        if self.resolve_path:
            path = os.path.realpath(os.path.abspath(path))
        if not os.path.exists(path):
            if self.exists:
                self.fail(f"{value!r} does not exist.", param, ctx)
            return self._result(path)
        if os.path.isdir(path):
            if not self.dir_okay:
                self.fail(f"{value!r} is a directory.", param, ctx)
        elif not self.file_okay:
            self.fail(f"{value!r} is a file.", param, ctx)
        if self.readable and not os.access(path, os.R_OK):
            self.fail(f"{value!r} is not readable.", param, ctx)
        if self.writable and not os.access(path, os.W_OK):
            self.fail(f"{value!r} is not writable.", param, ctx)
        if self.executable and not os.access(path, os.X_OK):
            self.fail(f"{value!r} is not executable.", param, ctx)
        return self._result(path)

    def shell_complete(self, ctx, param, incomplete):
        kind = "dir" if (self.dir_okay and not self.file_okay) else "file"
        return [PathRequest(kind, incomplete)]


class FuncParamType(ParamType):
    """Adapts a conversion function ``f(token) -> value`` that refuses with ``ValueError``."""

    def __init__(self, func: t.Callable[[t.Any], t.Any]) -> None:
        self.func = func
        self.name = getattr(func, "__name__", "text")

    def convert(self, value, param=None, ctx=None):
        try:
            return self.func(value)
        except BadParameter:
            raise
        except ValueError as e:
            self.fail(str(e) or f"{value!r} is not valid.", param, ctx)


STRING = StringParamType()
INT = IntParamType()
FLOAT = FloatParamType()
BOOL = BoolParamType()
UUID = UUIDParamType()
UNPROCESSED = UnprocessedParamType()

_PY_TYPES = {str: STRING, int: INT, float: FLOAT, bool: BOOL, uuid.UUID: UUID}


def _infer_from_default(default: t.Any) -> ParamType:
    if isinstance(default, bool):
        return BOOL
    if isinstance(default, int):
        return INT
    if isinstance(default, float):
        return FLOAT
    if isinstance(default, str):
        return STRING
    return STRING


def convert_type(ty: t.Any, default: t.Any = None) -> ParamType:
    """Return a :class:`ParamType` for ``ty``, inferring it from ``default`` when ``ty`` is None."""
    if ty is None:
        if default is None or callable(default):
            return STRING
        if isinstance(default, (list, tuple)):
            if not default:
                return STRING
            return _infer_from_default(default[0])
        return _infer_from_default(default)
    if isinstance(ty, ParamType):
        return ty
    if isinstance(ty, type):
        if issubclass(ty, ParamType):
            return ty()
        if ty in _PY_TYPES:
            return _PY_TYPES[ty]
    if callable(ty):
        return FuncParamType(ty)
    raise TypeError(f"Unsupported parameter type: {ty!r}")

