class Context:
    """The state of one invocation of a command.

    Built by the library. Settings come from ``main(**extra)``, from the
    command's ``context_settings`` and from the parent context.
    """

    def __init__(
        self,
        command: "Command",
        parent: t.Optional["Context"] = None,
        info_name: t.Optional[str] = None,
        obj: t.Any = None,
        default_map: t.Optional[t.Dict[str, t.Any]] = None,
        **settings: t.Any,
    ) -> None:
        self.command = command
        self.parent = parent
        self.info_name = info_name
        self.params: t.Dict[str, t.Any] = {}
        self._sources: t.Dict[str, ParameterSource] = {}
        self._ranks: t.Dict[str, t.Tuple[int, int, int]] = {}
        self.invoked_subcommand: t.Optional[str] = None
        self.resilient_parsing = False
        self._rest: t.List[str] = []
        self._close_callbacks: t.List[t.Callable[[], t.Any]] = []
        self._depth = 0

        merged = dict(command.context_settings)
        merged.update({k: v for k, v in settings.items() if v is not None})

        def inherit(key: str) -> t.Any:
            if merged.get(key) is not None:
                return merged[key]
            if parent is not None:
                return getattr(parent, key)
            return _MAP_SETTINGS[key]

        self.obj = obj if obj is not None else (parent.obj if parent is not None else None)
        self.auto_envvar_prefix = inherit("auto_envvar_prefix")
        self.terminal_width = inherit("terminal_width")
        self.max_content_width = inherit("max_content_width")
        self.help_option_names = list(inherit("help_option_names") or ["--help"])
        self.token_normalize_func = inherit("token_normalize_func")
        self.color = inherit("color")
        self.show_default = inherit("show_default")
        self.ignore_unknown_options = inherit("ignore_unknown_options")
        self.allow_extra_args = merged.get("allow_extra_args", command.allow_extra_args)
        self.allow_interspersed_args = merged.get(
            "allow_interspersed_args", command.allow_interspersed_args
        )
        if default_map is None:
            default_map = merged.get("default_map")
        self.default_map = default_map

    # -- structure -------------------------------------------------------

    @property
    def command_path(self) -> str:
        parts = []
        node: t.Optional[Context] = self
        while node is not None:
            if node.info_name:
                parts.append(node.info_name)
            node = node.parent
        return " ".join(reversed(parts))

    def find_root(self) -> "Context":
        node = self
        while node.parent is not None:
            node = node.parent
        return node

    def find_object(self, object_type: type) -> t.Any:
        node: t.Optional[Context] = self
        while node is not None:
            if isinstance(node.obj, object_type):
                return node.obj
            node = node.parent
        return None

    def ensure_object(self, object_type: type) -> t.Any:
        found = self.find_object(object_type)
        if found is None:
            found = object_type()
            self.obj = found
        return found

    # -- scope and cleanup ----------------------------------------------

    def __enter__(self) -> "Context":
        self._depth += 1
        push_context(self)
        return self

    def __exit__(self, *exc_info: t.Any) -> None:
        self._depth -= 1
        pop_context()

    def call_on_close(self, func: t.Callable[[], t.Any]) -> t.Callable[[], t.Any]:
        self._close_callbacks.append(func)
        return func

    def with_resource(self, cm: t.Any) -> t.Any:
        value = cm.__enter__()
        self.call_on_close(lambda: cm.__exit__(None, None, None))
        return value

    def close(self) -> None:
        callbacks, self._close_callbacks = self._close_callbacks, []
        for func in reversed(callbacks):
            func()

    # -- control ----------------------------------------------------------

    def exit(self, code: int = 0) -> t.NoReturn:
        raise Exit(code)

    def abort(self) -> t.NoReturn:
        raise Abort()

    def get_parameter_source(self, name: str) -> t.Optional[ParameterSource]:
        if name not in {p.name for p in self.command.get_params(self)}:
            return None
        return self._sources.get(name)

    def get_help(self) -> str:
        return self.command.get_help(self)

    def get_usage(self) -> str:
        return self.command.get_usage(self)

    def get_wrap_width(self) -> int:
        if self.terminal_width is not None:
            return self.terminal_width
        try:
            columns = shutil.get_terminal_size((80, 24)).columns
        except OSError:
            columns = 80
        return min(columns, self.max_content_width)

    def invoke(self, callback: t.Any, *args: t.Any, **kwargs: t.Any) -> t.Any:
        """Run a command or a plain function from inside a callback.

        A command runs with the given values; missing parameters take their
        declared defaults. A plain function is called with the given arguments.
        """
        if isinstance(callback, Command):
            child = Context(callback, parent=self, info_name=callback.name)
            for param in callback.params:
                if param.expose_value and param.name not in kwargs:
                    kwargs[param.name] = param.get_default(child)
            child.params.update(kwargs)
