        self.multiple = False
        self.metavar: t.Optional[str] = None
        self.expose_value = True
        self.is_eager = False
        self.envvar: t.Optional[t.List[str]] = None
        self.allow_from_autoenv = True
        self.shell_complete_func: t.Optional[t.Callable[..., t.Any]] = None
