        node: t.Optional[Context] = ctx
        while node is not None and node.parent is not None:
            chain.append(node.info_name or "")
            node = node.parent
        parts = [prefix] + list(reversed(chain)) + [self.name]
        return "_".join(p.replace("-", "_") for p in parts if p).upper()

