            return [tuple(tokens[i : i + n]) for i in range(0, len(tokens), n)]
        if len(tokens) != n:
            raise BadOptionUsage(f"{self.get_error_hint(ctx)} takes {n} values.", ctx)
        return [tuple(tokens)]

    def _as_occurrence(self, value: t.Any, ctx: "Context") -> t.Tuple[t.Any, ...]:
        if self.nargs > 1 or isinstance(self.type, Tuple):
            if isinstance(value, (str, bytes)) or not isinstance(value, (list, tuple)):
                raise BadOptionUsage(
                    f"{self.get_error_hint(ctx)} needs a sequence of {self.nargs} values.", ctx
                )
            return tuple(value)
        return (value,)

    def _occurrences_from_value(self, value: t.Any, ctx: "Context", from_map: bool) -> t.List[t.Any]:
        if self.multiple:
            if isinstance(value, (str, bytes)) or not isinstance(value, (list, tuple)):
                raise BadOptionUsage(
                    f"{self.get_error_hint(ctx)} needs an iterable (sequence) default, "
                    "not a single value.",
                    ctx,
                )
            return [self._as_occurrence(v, ctx) for v in value]
        if isinstance(value, str) and (self.nargs > 1 or isinstance(self.type, Tuple)):
            return self._chunk(self.type.split_envvar_value(value), ctx)
        return [self._as_occurrence(value, ctx)]

    def _shape(self, ctx: "Context", occurrences: t.List[t.Tuple[t.Any, ...]]) -> t.Any:
        if self.nargs == -1:
            flat: t.List[t.Any] = []
            for occ in occurrences:
                flat.extend(occ)
            return tuple(self.type.convert(v, self, ctx) for v in flat)
        converted = []
        for occ in occurrences:
            if isinstance(self.type, Tuple):
                converted.append(self.type.convert(occ, self, ctx))
            elif self.nargs > 1:
                converted.append(tuple(self.type.convert(v, self, ctx) for v in occ))
            else:
                converted.append(self.type.convert(occ[0], self, ctx))
        if self.multiple:
            return tuple(converted)
        if not converted:
            return None
        return converted[-1]

    def _env_value(self, ctx: "Context") -> t.Tuple[bool, t.Any]:
        """Return (supplied, value) for the environment source."""
        raw = self._env_raw(ctx)
        if raw is None:
            return False, None
        if self.is_flag:
            value = self._env_flag(ctx, raw)
            return (value is not None), value
        if self.nargs == 1 and not self.multiple and not isinstance(self.type, Tuple):
            occurrences = [(raw,)]
        else:
            tokens = self.type.split_envvar_value(raw)
