            is_flag = True
        if is_flag is None:
            is_flag = isinstance(default, bool) and not self.multiple
        if is_flag is None and flag_value is not None:
            is_flag = True
        if is_flag is None:
            is_flag = False
        if count and is_flag:
            raise TypeError("A counting option cannot also be a flag.")
        if count and self.multiple:
            raise TypeError("A counting option cannot be repeatable.")

        self.is_flag = bool(is_flag)
        self.count = count
        self.optional_value = (not self.is_flag) and flag_value is not None and not count
        if self.is_flag:
            self.flag_value = True if flag_value is None else flag_value
            if default is None:
                default = self.flag_value if False else False
        elif self.optional_value:
            self.flag_value = flag_value
        if count and default is None:
            default = 0

        if nargs is None:
            if isinstance(type_arg, Tuple):
                nargs = type_arg.arity
            elif isinstance(default, tuple) and self.multiple is False and isinstance(type_arg, Tuple):
                nargs = len(default)
            else:
                nargs = 1
        if not isinstance(nargs, int) or nargs < 1:
            raise TypeError("'nargs' must be a positive integer for options.")
        if self.is_flag or count:
            nargs = 1
        self.nargs = nargs

        self.default = default
        self.default_explicit = default is not None and not (self.is_flag and default is False)
        if self.is_flag and default is None:
            self.default_explicit = False
        if self.default is None and not self.is_flag and not count and self.multiple:
            self.default = None

        if type_arg is None and not self.is_flag and not count:
            type_hint = default
            if isinstance(default, tuple) and nargs > 1:
                type_hint = default
            self.type = convert_type(None, type_hint) if not isinstance(default, tuple) or nargs == 1 else convert_type(None, default)
            if self.multiple and isinstance(default, (list, tuple)) and default:
                self.type = convert_type(None, default[0])
        elif self.is_flag or count:
            self.type = BOOL if self.is_flag else convert_type(type_arg or "int")
        else:
            self.type = convert_type(type_arg, default)
        if type_arg is None and self.is_flag:
            self.type = BOOL
        if count and type_arg is None:
            from .paramtypes import INT

            self.type = INT
        if isinstance(self.type, Tuple) and nargs != self.type.arity:
            raise TypeError("A tuple type's length must match 'nargs'.")

        self.required = required
        self.prompt = _prompt_text_option(prompt)
        if prompt is not None and self.is_flag and self.multiple:
            raise TypeError("A flag cannot be repeatable and prompt.")
        self.allow_from_autoenv = bool(allow_autoenv)
        self.envvar = _listify(envvar)

        self.callback = attrs.pop("callback", None)
        self.is_eager = bool(attrs.pop("is_eager", False))
        self.expose_value = bool(attrs.pop("expose_value", True))
        self.hidden = bool(attrs.pop("hidden", False))
        deprecated = attrs.pop("deprecated", False)
        self.deprecated = bool(deprecated)
        self.deprecation_note = deprecated if isinstance(deprecated, str) else None
        self.help = attrs.pop("help", None)
        self.metavar = attrs.pop("metavar", None)
        self.show_default = attrs.pop("show_default", None)
        self.show_envvar = bool(attrs.pop("show_envvar", False))
        self.shell_complete_func = attrs.pop("shell_complete", None)
        if attrs:
            raise TypeError(f"Unknown option keyword(s): {', '.join(sorted(attrs))}")

        if self.deprecated and self.required:
            raise TypeError("A deprecated option cannot also be required.")
        if self.deprecated and self.prompt is not None:
            raise TypeError("A deprecated option cannot use a prompt.")
        if self.is_flag and self.nargs != 1:
            raise TypeError("A flag takes no values.")

    def get_error_hint(self, ctx: t.Any = None) -> str:
        names = list(self.opts)
        if self.secondary_opts:
            return "/".join(filter(None, [", ".join(self.opts), ", ".join(self.secondary_opts)])).join(["'", "'"])
        return " / ".join(f"'{n}'" for n in names)

    def get_help_metavar(self) -> t.Optional[str]:
        if self.is_flag or self.count:
            return None
        if self.optional_value:
            return f"[{self.metavar or self.name.upper()}]"
        if self.metavar is not None:
            return self.metavar
        if isinstance(self.type, Choice):
            return self.type.get_metavar()
        if isinstance(self.type, Tuple):
            return self.type.get_metavar()
        base = self.name.upper()
        if self.nargs > 1:
            return " ".join([base] * self.nargs)
        return base

    def flag_value_for(self, role: str) -> t.Any:
        if role == "off":
            return False
        return self.flag_value


class Argument(Parameter):
    """A positional parameter bound in declaration order."""

    param_kind = "argument"

    def __init__(self, param_decls: t.Sequence[str], **attrs: t.Any) -> None:
        if len(param_decls) != 1 or not str(param_decls[0]).isidentifier():
            raise TypeError("An argument takes exactly one destination name.")
        super().__init__(str(param_decls[0]))
        nargs = attrs.pop("nargs", 1)
        if nargs != -1 and (not isinstance(nargs, int) or nargs < 1):
            raise TypeError("'nargs' must be a positive integer or -1 for arguments.")
        self.nargs = nargs
        self.multiple = False
        default = attrs.pop("default", None)
        required = attrs.pop("required", None)
        if nargs == -1:
            self.required = required is True
        elif required is None:
            self.required = default is None
        else:
            self.required = bool(required)
        self.default = default
        self.default_explicit = default is not None
        type_arg = attrs.pop("type", None)
        if isinstance(type_arg, Tuple):
            if nargs == 1:
                self.nargs = type_arg.arity
        self.type = convert_type(type_arg, default if nargs != -1 else None)
        self.envvar = _listify(attrs.pop("envvar", None))
        deprecated = attrs.pop("deprecated", False)
        self.deprecated = bool(deprecated)
        self.deprecation_note = deprecated if isinstance(deprecated, str) else None
        if self.deprecated and self.required:
            raise TypeError("A deprecated argument cannot be required.")
        self.help = attrs.pop("help", None)
        self.metavar = attrs.pop("metavar", None)
        self.expose_value = True
        self.hidden = bool(attrs.pop("hidden", False))
        self.callback = attrs.pop("callback", None)
        self.is_eager = False
        self.shell_complete_func = attrs.pop("shell_complete", None)
        if attrs:
            raise TypeError(f"Unknown argument keyword(s): {', '.join(sorted(attrs))}")

    def get_error_hint(self, ctx: t.Any = None) -> str:
        return f"'{self.name}'"

    def get_placeholder(self) -> str:
        if self.metavar is not None:
            base = self.metavar
        elif isinstance(self.type, Tuple):
            base = self.type.get_metavar()
        else:
            base = self.name.upper()
        if self.nargs == -1:
            return base + "..."
        if self.nargs > 1 and self.metavar is None and not isinstance(self.type, Tuple):
            return " ".join([base] * self.nargs)
        return base

    def get_usage_piece(self) -> str:
        placeholder = self.get_placeholder()
        if self.nargs == -1:
            return placeholder if self.required else f"[{placeholder.rstrip('.')}]..."
        return placeholder if self.required else f"[{placeholder}]"


def _listify(value: t.Any) -> t.Optional[t.List[str]]:
    if value is None:
        return None
    if isinstance(value, str):
        return [value]
    return list(value)


def _prompt_text_option(prompt: t.Any) -> t.Optional[str]:
    if prompt is None or prompt is False:
        return None
    if prompt is True:
        return ""
    return str(prompt)


def _split_prefix(name: str) -> t.Tuple[str, str]:
    prefix = name[0]
    return prefix, name


def _parse_option_decls(decls: t.Sequence[str]) -> t.Tuple[t.Optional[str], t.List[str], t.List[str]]:
    dest: t.Optional[str] = None
    opts: t.List[str] = []
    secondary: t.List[str] = []
    for decl in decls:
        decl = str(decl)
        if decl and decl[0] in "-/+":
            if "/" in decl[1:]:
                left, right = decl.split("/", 1)
                if not left or not right:
                    raise TypeError(f"Invalid on/off option declaration {decl!r}.")
                opts.append(left)
                secondary.append(right)
            else:
                opts.append(decl)
        elif decl.isidentifier():
            if dest is not None:
                raise TypeError("An option takes only one destination name.")
            dest = decl
        else:
            raise TypeError(f"Invalid option declaration {decl!r}.")
    return dest, opts, secondary


def _infer_dest(opts: t.List[str]) -> str:
    long_names = [o for o in opts if len(o.lstrip("-/+")) > 1 and o[:2] == o[0] * 2]
    chosen = long_names[0] if long_names else opts[0]
    return chosen.lstrip("-/+").replace("-", "_")


class _OptionParser:
    """Turns option tokens into per-parameter occurrences and collects the rest."""

    def __init__(
        self,
        ctx: Context,
        options: t.List[Option],
        interspersed: bool,
        passthrough: bool,
        ignore_unknown: bool,
    ) -> None:
        self.ctx = ctx
        self.normalize = ctx.token_normalize_func or (lambda s: s)
        self.interspersed = interspersed
        self.passthrough = passthrough
        self.ignore_unknown = ignore_unknown
        self.opts: t.Dict[str, t.Tuple[Option, str]] = {}
        self.prefixes = {"-"}
        for option in options:
            for name in option.opts:
                self._register(name, option, "on")
            for name in option.secondary_opts:
                self._register(name, option, "off")
        self.occurrences: t.Dict[Parameter, t.List[t.Tuple[t.Any, ...]]] = {}
        self.first: t.Dict[Parameter, int] = {}
        self.largs: t.List[str] = []
        self.literal: t.Set[int] = set()

    def _register(self, name: str, option: Option, role: str) -> None:
        self.prefixes.add(name[0])
        self.opts[self.normalize(name)] = (option, role)

    def _is_option_like(self, token: str) -> bool:
        return len(token) > 1 and token[0] in self.prefixes

    def _is_known(self, token: str) -> bool:
        return self.normalize(token.partition("=")[0]) in self.opts

    def _record(self, param: Parameter, occ: t.Tuple[t.Any, ...]) -> None:
        self.first.setdefault(param, len(self.first))
        self.occurrences.setdefault(param, []).append(occ)

    def _add_positional(self, token: str, literal: bool = False) -> None:
        self.largs.append(token)
        if literal:
            self.literal.add(len(self.largs) - 1)

    def _unknown(self, token: str, name: str) -> None:
        if self.passthrough or self.ignore_unknown:
            self.largs.append(token)
            return
        raise NoSuchOption(name, ctx=self.ctx)

    def parse(self, args: t.Sequence[str]) -> None:
        i = 0
        after_dd = False
        n = len(args)
        while i < n:
            token = args[i]
            i += 1
            if after_dd:
                self._add_positional(token, literal=True)
                continue
            if token == "--":
                after_dd = True
                continue
            if not self._is_option_like(token):
                self._add_positional(token)
                if not self.interspersed:
                    self.largs.extend(args[i:])
                    break
                continue
            i = self._handle_option(token, args, i)

    def _handle_option(self, token: str, args: t.Sequence[str], i: int) -> int:
        name, eq, attached = token.partition("=")
        attached_value: t.Optional[str] = attached if eq else None
        entry = self.opts.get(self.normalize(name))
        if entry is not None:
            option, role = entry
            return self._take(option, role, name, attached_value, args, i)
        if len(token) > 1 and token[1] == token[0]:
            self._unknown(token, name)
            return i
        stack = token[1:]
        j = 0
        while j < len(stack):
            short = token[0] + stack[j]
            entry = self.opts.get(self.normalize(short))
            if entry is None:
                if self.passthrough or self.ignore_unknown:
                    self.largs.append(token[0] + stack[j:])
                    return i
                raise NoSuchOption(short, ctx=self.ctx)
            option, role = entry
            if option.is_flag or option.count:
                self._record_flag(option, role)
                j += 1
                continue
            rest = stack[j + 1 :]
            return self._take(option, role, short, rest or None, args, i)
        return i

    def _record_flag(self, option: Option, role: str) -> None:
        if option.count:
            self._record(option, ("count",))
        else:
            self._record(option, ("const", option.flag_value_for(role)))

    def _take(
        self,
        option: Option,
        role: str,
        name: str,
        attached: t.Optional[str],
        args: t.Sequence[str],
        i: int,
    ) -> int:
        if option.is_flag or option.count:
            if attached is not None:
                raise BadOptionUsage(f"Option '{name}' does not take a value.", self.ctx)
            self._record_flag(option, role)
            return i
        if option.optional_value:
            if attached is not None:
                self._record(option, ("tokens", (attached,)))
                return i
            if i < len(args) and not self._is_option_like(args[i]) and not self._is_known(args[i]):
                self._record(option, ("tokens", (args[i],)))
                return i + 1
            self._record(option, ("const", option.flag_value))
            return i
        nargs = option.nargs
        tokens: t.List[str] = []
        if attached is not None:
            if nargs == 1:
                self._record(option, ("tokens", (attached,)))
                return i
            tokens.append(attached)
        need = nargs - len(tokens)
        available = len(args) - i
        blocked = available > 0 and self._is_known(args[i])
        if need > 0 and (available < need or blocked):
            if option.prompt is not None and not tokens and (available == 0 or self._is_option_like(args[i])):
                self._record(option, ("prompt",))
                return i
            if nargs == 1:
                raise BadOptionUsage(f"Option '{name}' requires an argument.", self.ctx)
            raise BadOptionUsage(f"Option '{name}' requires {nargs} arguments.", self.ctx)
        tokens.extend(args[i : i + need])
        self._record(option, ("tokens", tuple(tokens)))
        return i + need


def _consume_arguments(
    arguments: t.List[Argument], tokens: t.List[str], literal: t.Set[int]
) -> t.Tuple[t.Dict[Argument, t.List[t.Tuple[t.Any, ...]]], t.List[t.Tuple[str, bool]]]:
    result: t.Dict[Argument, t.List[t.Tuple[t.Any, ...]]] = {}
    pos = 0
    for index, arg in enumerate(arguments):
        remaining = len(tokens) - pos
        if arg.nargs == -1:
            needed_after = sum(a.nargs for a in arguments[index + 1 :] if a.nargs > 0 and a.required)
            take = max(0, remaining - needed_after)
            result[arg] = [tuple(tokens[pos : pos + take])] if take else []
            pos += take
            continue
        need = arg.nargs
        if remaining >= need:
            result[arg] = [tuple(tokens[pos : pos + need])]
            pos += need
        elif remaining > 0:
            raise BadArgumentUsage(f"Argument '{arg.name}' takes {need} values.")
        else:
            result[arg] = []
    leftover = [(tok, (pos + k) in literal) for k, tok in enumerate(tokens[pos:])]
    return result, leftover


class Command:
    """A leaf command: parses its parameters and runs the author's callback."""

    allow_extra_args_default = False

    def __init__(
        self,
        name: t.Optional[str] = None,
        callback: t.Optional[t.Callable[..., t.Any]] = None,
        params: t.Optional[t.Iterable[Parameter]] = None,
        **attrs: t.Any,
    ) -> None:
        self.name = name
        self.callback = callback
        self.params: t.List[Parameter] = list(params or [])
        doc = attrs.pop("help", None)
        if doc is None and callback is not None:
            doc = callback.__doc__
        if doc is not None:
            doc = inspect.cleandoc(str(doc).split("\f", 1)[0])
        self.help: t.Optional[str] = doc
        self.short_help: t.Optional[str] = attrs.pop("short_help", None)
        self.epilog: t.Optional[str] = attrs.pop("epilog", None)
        self.options_metavar: t.Optional[str] = attrs.pop("options_metavar", "[OPTIONS]")
        self.context_settings: t.Dict[str, t.Any] = dict(attrs.pop("context_settings", None) or {})
        self.add_help_option: bool = bool(attrs.pop("add_help_option", True))
        self.no_args_is_help: bool = bool(attrs.pop("no_args_is_help", False))
        deprecated = attrs.pop("deprecated", False)
        self.deprecated = bool(deprecated)
        self.deprecation_note = deprecated if isinstance(deprecated, str) else None
        self.hidden: bool = bool(attrs.pop("hidden", False))
        self.allow_extra_args: bool = bool(attrs.pop("allow_extra_args", self.allow_extra_args_default))
        self.allow_interspersed_args: bool = bool(attrs.pop("allow_interspersed_args", True))
        if attrs:
            raise TypeError(f"Unknown command keyword(s): {', '.join(sorted(attrs))}")
        variadic = [p for p in self.params if isinstance(p, Argument) and p.nargs == -1]
        if len(variadic) > 1:
            raise TypeError("Only one variadic argument is allowed per command.")

    # -- introspection ----------------------------------------------------

    def __call__(self, *args: t.Any, **kwargs: t.Any) -> t.Any:
        return self.main(*args, **kwargs)

    def __repr__(self) -> str:
        return f"<{type(self).__name__} {self.name}>"

    def get_help_text(self) -> t.Optional[str]:
        return self.help

    def get_params(self, ctx: Context) -> t.List[Parameter]:
        params = list(self.params)
        if self.add_help_option:
            declared = {n for p in self.params if isinstance(p, Option) for n in p.opts + p.secondary_opts}
            names = [n for n in ctx.help_option_names if n not in declared]
            if names:
                params.append(_make_help_option(names))
        return params

    def get_short_help_str(self, limit: int = 45) -> str:
        if self.short_help is not None:
            text = self.short_help
        else:
            text = " ".join((self.help or "").split())
            match = _SENTENCE_RE.match(text)
            if match:
                text = match.group(0)
        if len(text) > limit:
            text = text[: max(limit - 3, 0)].rstrip() + "..."
        return text

    def get_usage(self, ctx: Context) -> str:
        pieces = [ctx.command_path]
        if self.options_metavar:
            pieces.append(self.options_metavar)
        for param in self.params:
            if isinstance(param, Argument):
                pieces.append(param.get_usage_piece())
        return "Usage: " + " ".join(p for p in pieces if p)

    def get_help(self, ctx: Context) -> str:
        width = ctx.get_wrap_width()
        out: t.List[str] = [self.get_usage(ctx), ""]
        if self.deprecated:
            mark = "(Deprecated)" if not self.deprecation_note else f"(Deprecated) {self.deprecation_note}"
            out.extend([mark, ""])
        text = self.get_help_text()
        if text:
            out.extend(rewrap_help(text, width))
            out.append("")
        arg_rows = [
            (p.get_usage_piece().strip("[]").rstrip("."), p.help)
            for p in self.params
            if isinstance(p, Argument) and p.help and not p.hidden
        ]
        if arg_rows:
            out.append("Positional arguments:")
            out.extend(_rows(arg_rows, width))
            out.append("")
        option_rows = []
        for param in self.get_params(ctx):
            if isinstance(param, Option) and not param.hidden:
                option_rows.append(_option_row(param, ctx, width))
        if option_rows:
            out.append("Options:")
            out.extend(_rows(option_rows, width))
            out.append("")
        if isinstance(self, Group):
            cmd_rows = []
            for name in self.list_commands(ctx):
                child = self.get_command(ctx, name)
                if child is None or child.hidden:
                    continue
                cmd_rows.append((name, child.get_short_help_str(max(width - 30, 20))))
            if cmd_rows:
                out.append("Commands:")
                out.extend(_rows(cmd_rows, width))
                out.append("")
        if self.epilog:
            out.extend(rewrap_help(self.epilog, width))
            out.append("")
        while out and out[-1] == "":
            out.pop()
        return "\n".join(out) + "\n"

    # -- parsing ----------------------------------------------------------

    def make_context(
        self,
        info_name: t.Optional[str],
        args: t.Sequence[str],
        parent: t.Optional[Context] = None,
        chained: bool = False,
        **extra: t.Any,
    ) -> Context:
        child_map = None
        if parent is not None and isinstance(parent.default_map, dict):
            child_map = parent.default_map.get(info_name or "")
            if not isinstance(child_map, dict):
                child_map = None
        ctx = Context(self, parent=parent, info_name=info_name, default_map=child_map, **extra)
        try:
            with ctx:
                ctx._rest = self._parse(ctx, list(args), chained)
        except BaseException:
            ctx.close()
            raise
        return ctx

    def parse_args(self, ctx: Context, args: t.Sequence[str]) -> t.List[str]:
        return self._parse(ctx, list(args), chained=False)

    def _parse(self, ctx: Context, args: t.List[str], chained: bool) -> t.List[str]:
        if not args and self.no_args_is_help and not ctx.resilient_parsing:
            echo(self.get_help(ctx), err=True)
            raise NoArgsIsHelp(ctx=ctx)
        params = self.get_params(ctx)
        options = [p for p in params if isinstance(p, Option)]
        arguments = [p for p in params if isinstance(p, Argument)]
        parser = _OptionParser(
            ctx,
            options,
            interspersed=bool(ctx.allow_interspersed_args),
            passthrough=isinstance(self, Group) and bool(ctx.allow_interspersed_args),
            ignore_unknown=bool(ctx.ignore_unknown_options),
        )
        parser.parse(args)
        arg_occurrences, leftover = _consume_arguments(arguments, parser.largs, parser.literal)
        occurrences = dict(parser.occurrences)
        occurrences.update(arg_occurrences)
        first = dict(parser.first)
        self._process(ctx, params, occurrences, first)
        if isinstance(self, Group):
            return [tok for tok, _ in leftover]
        if chained:
            return [tok for tok, _ in leftover]
        if leftover:
            if ctx.allow_extra_args:
                for tok, literal in leftover:
                    if not literal and len(tok) > 1 and tok[0] in parser.prefixes and not ctx.ignore_unknown_options:
                        raise NoSuchOption(tok, ctx=ctx)
                return []
            names = " ".join(tok for tok, _ in leftover)
            raise UsageError(
                f"Got unexpected extra argument{'s' if len(leftover) != 1 else ''} ({names})",
                ctx=ctx,
            )
        return []

    def _process(
        self,
        ctx: Context,
        params: t.List[Parameter],
        occurrences: t.Dict[Parameter, t.List[t.Tuple[t.Any, ...]]],
        first: t.Dict[Parameter, int],
    ) -> None:
        indexed = {id(p): i for i, p in enumerate(params)}
        seen_eager = sorted(
            (p for p in params if p.is_eager and p in first), key=lambda p: first[p]
        )
        unseen_eager = [p for p in params if p.is_eager and p not in first]
        rest = [p for p in params if not p.is_eager]
        for param in seen_eager + unseen_eager + rest:
            self._process_one(ctx, param, occurrences.get(param), indexed[id(param)])

    def _process_one(self, ctx: Context, param: Parameter, occurrences: t.Any, index: int) -> None:
        if isinstance(param, Option) and param.is_flag and param.prompt is not None:
            supplied = any(o[0] == "const" for o in (occurrences or []))
            env_supplied, env_value = (False, None) if supplied else param._env_value(ctx)
            if not supplied and not env_supplied:
                value = param._prompt_value(ctx, param.get_default(ctx))
                source = ParameterSource.PROMPT
            else:
                value, source = (env_value, ParameterSource.ENVIRONMENT) if env_supplied else (
                    [o for o in occurrences if o[0] == "const"][-1][1],
                    ParameterSource.COMMANDLINE,
                )
        else:
            value, source = param.process(ctx, occurrences)
        if source is None and param.required:
            raise MissingParameter(ctx=ctx, param=param)
        if value is None and (param.multiple or param.nargs == -1):
            value = ()
        if param.deprecated and source is ParameterSource.COMMANDLINE:
            _warn_deprecated_param(ctx, param)
        if param.callback is not None:
            try:
                value = param.callback(ctx, param, value)
            except BadParameter as e:
                if e.ctx is None:
                    e.ctx = ctx
                if e.param is None and e.param_hint is None:
                    e.param = param
                raise
        rank = param._rank(source, index)
        previous = ctx._ranks.get(param.name)
        if previous is None or rank >= previous:
            ctx._ranks[param.name] = rank
            ctx._sources[param.name] = source
            if param.expose_value:
                ctx.params[param.name] = value

    # -- running ------------------------------------------------------------

    def _run_callback(self, ctx: Context) -> t.Any:
        if self.callback is None:
            return None
        kwargs = {p.name: ctx.params[p.name] for p in self.params if p.expose_value and p.name in ctx.params}
        return ctx.invoke(self.callback, **kwargs)

    def invoke(self, ctx: Context) -> t.Any:
        try:
            with ctx:
                if self.deprecated:
                    _warn_deprecated_command(ctx, self)
                return self._run_callback(ctx)
        finally:
            ctx.close()

    def main(
        self,
        args: t.Optional[t.Sequence[str]] = None,
        prog_name: t.Optional[str] = None,
        complete_var: t.Optional[str] = None,
        standalone_mode: bool = True,
        **extra: t.Any,
    ) -> t.Any:
        """Run this command as a program (or in-process when standalone mode is off)."""
        args = list(sys.argv[1:] if args is None else args)
        if prog_name is None:
            prog_name = os.path.basename(sys.argv[0] or "") or "main"
            if prog_name.endswith(".py"):
                prog_name = prog_name[:-3]
        if complete_var is None:
            complete_var = "_" + prog_name.upper().replace("-", "_") + "_COMPLETE"
        instruction = os.environ.get(complete_var)
        if instruction:
            from .shell_completion import run_completion

            status = run_completion(self, args, prog_name, instruction)
            if standalone_mode:
                sys.exit(status)
            return None
        try:
            try:
                ctx = self.make_context(prog_name, args, **extra)
                rv = self.invoke(ctx)
                if not standalone_mode:
                    return rv
                sys.exit(0)
            except (EOFError, KeyboardInterrupt) as e:
                raise Abort() from e
        except Exit as e:
            if standalone_mode:
                sys.exit(e.exit_code)
            return None
        except Abort:
            if not standalone_mode:
                raise
            echo("Aborted!", err=True)
            sys.exit(1)
        except OptlynError as e:
            if not standalone_mode:
                raise
            e.show()
            sys.exit(e.exit_code)


class Group(Command):
    """A command that dispatches to named subcommands."""

    def __init__(
        self,
        name: t.Optional[str] = None,
        commands: t.Any = None,
        invoke_without_command: bool = False,
        no_args_is_help: t.Optional[bool] = None,
        subcommand_metavar: t.Optional[str] = None,
        chain: bool = False,
        result_callback: t.Optional[t.Callable[..., t.Any]] = None,
        **kwargs: t.Any,
    ) -> None:
        kwargs.setdefault("allow_interspersed_args", False)
        if no_args_is_help is None:
            no_args_is_help = not invoke_without_command
        super().__init__(name, no_args_is_help=no_args_is_help, **kwargs)
        self.commands: t.Dict[str, Command] = {}
        if isinstance(commands, dict):
            for key, cmd in commands.items():
                self.add_command(cmd, key)
        elif commands:
            for cmd in commands:
                self.add_command(cmd)
        self.invoke_without_command = bool(invoke_without_command)
        self.subcommand_metavar = subcommand_metavar
        self.chain = bool(chain)
        self._result_callback = result_callback

    def add_command(self, cmd: Command, name: t.Optional[str] = None) -> None:
        if self.chain and isinstance(cmd, Group):
            raise TypeError("Groups cannot be nested under a chaining group.")
        key = name or cmd.name
        if not key:
            raise TypeError("A subcommand needs a name.")
        self.commands[key] = cmd

    def command(self, *args: t.Any, **kwargs: t.Any) -> t.Callable[[t.Callable[..., t.Any]], Command]:
        from .decorators import command as command_decorator

        def decorator(f: t.Callable[..., t.Any]) -> Command:
            cmd = command_decorator(*args, **kwargs)(f)
            self.add_command(cmd)
            return cmd

        return decorator

    def group(self, *args: t.Any, **kwargs: t.Any) -> t.Callable[[t.Callable[..., t.Any]], "Group"]:
        from .decorators import group as group_decorator

        def decorator(f: t.Callable[..., t.Any]) -> Group:
            grp = group_decorator(*args, **kwargs)(f)
            self.add_command(grp)
            return grp

        return decorator

    def result_callback(self) -> t.Callable[[t.Callable[..., t.Any]], t.Callable[..., t.Any]]:
        def decorator(f: t.Callable[..., t.Any]) -> t.Callable[..., t.Any]:
            self._result_callback = f
            return f

        return decorator

    def list_commands(self, ctx: Context) -> t.List[str]:
        return sorted(self.commands)

    def get_command(self, ctx: Context, cmd_name: str) -> t.Optional[Command]:
        return self.commands.get(cmd_name)

    def _lookup(self, ctx: Context, name: str) -> t.Optional[Command]:
        cmd = self.get_command(ctx, name)
        if cmd is None and ctx.token_normalize_func is not None:
            wanted = ctx.token_normalize_func(name)
            for candidate in self.list_commands(ctx):
                if ctx.token_normalize_func(candidate) == wanted:
                    cmd = self.get_command(ctx, candidate)
                    break
        return cmd

    def _parse_group(self, ctx: Context, args: t.List[str], chained: bool) -> t.List[str]:
        return self._parse(ctx, args, chained)

    def invoke(self, ctx: Context) -> t.Any:
        try:
            with ctx:
                if self.deprecated:
                    _warn_deprecated_command(ctx, self)
                if self.chain:
                    return self._invoke_chain(ctx)
                rest = ctx._rest
                if not rest:
                    if not self.invoke_without_command:
                        raise MissingCommand(ctx=ctx)
                    ctx.invoked_subcommand = None
                    rv = self._run_callback(ctx)
                    return self._finish(ctx, rv)
                name, child_args = rest[0], rest[1:]
                cmd = self._lookup(ctx, name)
                if cmd is None:
                    raise NoSuchCommand(name, ctx=ctx)
                ctx.invoked_subcommand = name
                self._run_callback(ctx)
                child = cmd.make_context(name, child_args, parent=ctx)
                rv = child.command.invoke(child)
                return self._finish(ctx, rv)
        finally:
            ctx.close()

    def _finish(self, ctx: Context, value: t.Any) -> t.Any:
        if self._result_callback is None:
            return value
        return ctx.invoke(self._result_callback, value, **ctx.params)

    def _invoke_chain(self, ctx: Context) -> t.List[t.Any]:
        subs: t.List[Context] = []
        rest = ctx._rest
        while rest:
            name = rest[0]
            cmd = self._lookup(ctx, name)
            if cmd is None:
                raise NoSuchCommand(name, ctx=ctx)
            sub = cmd.make_context(name, rest[1:], parent=ctx, chained=True)
            rest = sub._rest
            subs.append(sub)
        if not subs and not self.invoke_without_command:
            raise MissingCommand(ctx=ctx)
        ctx.invoked_subcommand = CHAIN_SENTINEL
        self._run_callback(ctx)
        results = [sub.command.invoke(sub) for sub in subs]
        if self._result_callback is not None:
            ctx.invoke(self._result_callback, results, **ctx.params)
        return results


class CommandCollection(Group):
    """A group whose subcommands are the union of several source groups."""

    def __init__(self, name: t.Optional[str] = None, sources: t.Optional[t.Iterable[Group]] = None, **kwargs: t.Any) -> None:
        super().__init__(name, **kwargs)
        self.sources: t.List[Group] = list(sources or [])

    def list_commands(self, ctx: Context) -> t.List[str]:
        names: t.Set[str] = set(self.commands)
        for source in self.sources:
            names.update(source.list_commands(ctx))
        return sorted(names)

    def get_command(self, ctx: Context, cmd_name: str) -> t.Optional[Command]:
        if cmd_name in self.commands:
            return self.commands[cmd_name]
        for source in self.sources:
            cmd = source.get_command(ctx, cmd_name)
            if cmd is not None:
                return cmd
        return None


def _make_help_option(names: t.List[str]) -> Option:
    def _callback(ctx: Context, param: Parameter, value: t.Any) -> None:
        if not value or ctx.resilient_parsing:
            return
        echo(ctx.get_help(), color=ctx.color)
        ctx.exit()

    return Option(
        names,
        is_flag=True,
        expose_value=False,
        is_eager=True,
        callback=_callback,
        help="Show this message and exit.",
        default=False,
    )


def _option_row(option: Option, ctx: Context, width: int) -> t.Tuple[str, str]:
    names = ", ".join(option.opts)
    if option.secondary_opts:
        names = f"{names}/{', '.join(option.secondary_opts)}"
    metavar = option.get_help_metavar()
    first = f"{names} {metavar}" if metavar else names
    parts: t.List[str] = []
    if option.help:
        parts.append(" ".join(option.help.split()))
    if option.deprecated:
        parts.append("(deprecated)" if not option.deprecation_note else f"(deprecated: {option.deprecation_note})")
    show = option.show_default if option.show_default is not None else ctx.show_default
    if show:
        default_text = _default_text(option, show)
        if default_text is not None:
            parts.append(f"[default: {default_text}]")
    if option.show_envvar:
        names_env = option.get_envvar_names(ctx)
        if names_env:
            parts.append(f"[env var: {', '.join(names_env)}]")
    return first, " ".join(parts)


def _default_text(param: Parameter, show: t.Any) -> t.Optional[str]:
    if isinstance(show, str):
        return show
    default = param.default
    if callable(default):
        return "(dynamic)"
    if default is None:
        return None
    if param.is_flag and default is False:
        return None
    if isinstance(default, (list, tuple)):
        return ", ".join(str(v) for v in default) if default else None
    return str(default)


def _rows(rows: t.List[t.Tuple[str, str]], width: int) -> t.List[str]:
    if not rows:
        return []
    col = min(max(len(first) for first, _ in rows) + 2, 30)
    text_width = max(width - col - 4, 20)
    lines: t.List[str] = []
    for first, second in rows:
        wrapped = textwrap.wrap(second, text_width) if second else []
        if len(first) + 2 > col or not wrapped:
            lines.append("  " + first)
            for line in wrapped:
                lines.append(" " * (col + 2) + line)
            continue
        lines.append("  " + first.ljust(col) + wrapped[0])
        for line in wrapped[1:]:
            lines.append(" " * (col + 2) + line)
    return lines


def _warn_deprecated_command(ctx: Context, cmd: Command) -> None:
    note = cmd.deprecation_note
    message = f"DeprecationWarning: The command '{ctx.command_path}' is deprecated."
    if note:
        message += f" {note}"
    echo(message, err=True)


def _warn_deprecated_param(ctx: Context, param: Parameter) -> None:
    note = param.deprecation_note
    if param.param_kind == "option":
        label = f"option '{param.opts[0] if param.opts else param.name}'"
    else:
        label = f"argument '{param.name}'"
    message = f"DeprecationWarning: The {label} is deprecated."
    if note:
        message += f" {note}"
    echo(message, err=True)


def _format_error_hint(param: Parameter, ctx: t.Any) -> str:
    return param.get_error_hint(ctx)
