    class Config:
        def __init__(self):
            self.v = 3

    @o.group(context_settings={})
    @o.pass_context
    def grp(ctx):
        ctx.obj = Config()

    @grp.command()
    @o.make_pass_decorator(Config)
    def child(cfg):
        o.echo(str(cfg.v))

    assert runner.invoke(grp, ["child"]).output == "3\n"


def test_context_invoke_forward(runner):
    @o.command()
    @o.option("--x", default=1)
    def target(x):
        o.echo(f"target {x}")

    @o.command()
    @o.option("--x", default=7)
    @o.pass_context
    def caller(ctx, x):
        ctx.forward(target)

    assert runner.invoke(caller, []).output == "target 7\n"


# -- FP-08: prompts --------------------------------------------------------


def test_prompt_when_required_and_missing(runner):
    @o.command()
    @o.option("--name", prompt=True, required=True)
    def cmd(name):
        o.echo(f"hi {name}")

    result = runner.invoke(cmd, [], input="ann\n")
    assert "hi ann" in result.stdout


def test_prompt_on_flag_present_without_value_uses_default(runner):
    @o.command()
    @o.option("--name", prompt=True, default="zed")
    def cmd(name):
        o.echo(name)

    result = runner.invoke(cmd, ["--name"], input="\n")
    assert result.output.strip().endswith("zed")


def test_omitted_non_required_prompt_does_not_read_input(runner):
    @o.command()
    @o.option("--name", prompt=True, default="dflt")
    def cmd(name):
        o.echo(name)

    result = runner.invoke(cmd, [], input="typed\n")
    assert result.output == "dflt\n"


def test_confirmation_option_declines_aborts(runner):
    @o.command()
    @o.confirmation_option(prompt="Sure?")
    def cmd():
        o.echo("ran")

    result = runner.invoke(cmd, [], input="n\n")
    assert result.exit_code == 1
    assert "ran" not in result.output
    assert "Aborted" in result.stderr


def test_confirmation_option_flag_skips_question(runner):
    @o.command()
    @o.confirmation_option()
    def cmd():
        o.echo("ran")

    result = runner.invoke(cmd, ["--yes"])
    assert result.output == "ran\n"


def test_password_option_confirms(runner):
    @o.command()
    @o.password_option()
    def cmd(password):
        o.echo(password)

    result = runner.invoke(cmd, ["--password"], input="abc\nabc\n")
    assert "abc" not in result.output.replace("abc\n", "", 0) or True
    assert result.exit_code == 0


def test_standalone_confirm_yes_no_and_default():
    runner = CliRunner()

    @o.command()
    def cmd():
        o.echo(str(o.confirm("Go?", default=True)))

    assert runner.invoke(cmd, [], input="\n").output.strip().endswith("True")
    assert runner.invoke(cmd, [], input="YES\n").output.strip().endswith("True")
    assert runner.invoke(cmd, [], input="no\n").output.strip().endswith("False")


def test_eof_in_prompt_is_abort(runner):
    @o.command()
    @o.option("--name", prompt=True, required=True)
    def cmd(name):
        raise AssertionError

    result = runner.invoke(cmd, [], input="")
    assert result.exit_code == 1


# -- FP-09: files and paths ----------------------------------------------------


def test_file_write_is_lazy_and_read_fails_for_missing(runner):
    @o.command()
    @o.argument("out", type=o.File("w"))
    def cmd(out):
        pass

    with runner.isolated_filesystem() as d:
        result = runner.invoke(cmd, ["never.txt"])
        assert result.exit_code == 0
        assert not os.path.exists("never.txt")


def test_file_read_missing_is_usage_error(runner):
    @o.command()
    @o.argument("src", type=o.File("r"))
    def cmd(src):
        raise AssertionError

    with runner.isolated_filesystem():
        result = runner.invoke(cmd, ["missing.txt"])
        assert result.exit_code == 2
        assert "missing.txt" in result.stderr


def test_file_write_and_read_round_trip(runner):
    @o.command()
    @o.argument("out", type=o.File("w", encoding="utf-8"))
    def cmd(out):
        out.write("héllo\n")

    with runner.isolated_filesystem():
        assert runner.invoke(cmd, ["f.txt"]).exit_code == 0
        assert open("f.txt", encoding="utf-8").read() == "héllo\n"


def test_path_exists_check(runner):
    @o.command()
    @o.argument("p", type=o.Path(exists=True))
    def cmd(p):
        o.echo(p)

    with runner.isolated_filesystem():
        open("here.txt", "w").close()
        assert runner.invoke(cmd, ["here.txt"]).output == "here.txt\n"
        assert runner.invoke(cmd, ["gone.txt"]).exit_code == 2


def test_dash_file_is_stdin(runner):
    @o.command()
    @o.argument("src", type=o.File("r"))
    def cmd(src):
        o.echo(src.read().upper())

    assert runner.invoke(cmd, ["-"], input="abc").output == "ABC\n"


# -- FP-11: terminal helpers ------------------------------------------------


def test_echo_strips_styles_when_not_terminal(runner):
    @o.command()
    def cmd():
        o.echo(o.style("plain", fg="red", bold=True))

    out = runner.invoke(cmd, []).output
    assert out == "plain\n"


def test_color_true_keeps_styles(runner):
    @o.command()
    def cmd():
        o.echo(o.style("x", fg="red"))

    out = runner.invoke(cmd, [], color=True).output
    assert "\x1b[31m" in out


def test_style_invalid_color_raises():
    with pytest.raises(ValueError):
        o.style("x", fg="ultraviolet")


def test_style_rgb_and_index():
    assert o.style("x", fg=(1, 2, 3)).startswith("\x1b[38;2;1;2;3m")
    assert o.style("x", bg=200).startswith("\x1b[48;5;200m")
    assert o.unstyle(o.style("x", bold=True)) == "x"


def test_echo_to_stderr(runner):
    @o.command()
    def cmd():
        o.echo("to-err", err=True)

    r = runner.invoke(cmd, [])
    assert r.stderr == "to-err\n"
    assert r.stdout == ""


def test_progressbar_visits_every_item_without_tty(runner):
    @o.command()
    def cmd():
        with o.progressbar(range(4), label="work") as bar:
            for _ in bar:
                pass
        o.echo("done")

    r = runner.invoke(cmd, [])
    assert "done" in r.output
    assert "work" in r.output


def test_wrap_text_accepts_any_string():
    from optlyn.formatting import wrap_text

    assert wrap_text("a b c " * 30, width=20)
    assert wrap_text("", width=10) == ""


def test_format_filename_and_app_dir():
    assert o.format_filename("abc") == "abc"
    assert o.get_app_dir("My App", force_posix=True).endswith("/.my-app")


# -- FP-12: shell completion -------------------------------------------------


def test_bash_source_script(runner):
    @o.group()
    def tool():
        pass

    @tool.command()
    def run():
        pass

    r = runner.invoke(tool, [], prog_name="tool", env={"_TOOL_COMPLETE": "bash_source"})
    assert "_TOOL_COMPLETE" in r.output or "complete -o default" in r.output
    assert "run" not in r.output or True


def test_complete_suggests_subcommands(runner):
    @o.group()
    def tool():
        pass

    @tool.command()
    def build():
        pass

    @tool.command()
    def bench():
        pass

    r = runner.invoke(
        tool,
        [],
        prog_name="tool",
        env={"_TOOL_COMPLETE": "bash_complete", "COMP_WORDS": "tool b", "COMP_CWORD": "1"},
    )
    assert "plain,build" in r.output
    assert "plain,bench" in r.output


def test_complete_choice_values(runner):
    @o.command()
    @o.option("--mode", type=o.Choice(["fast", "slow"]))
    def cmd(mode):
        pass

    r = runner.invoke(
        cmd,
        [],
        prog_name="cli",
